import type { StoragePort } from '@allrice/contracts';
import {
  publishWorkbenchArtifact,
  ArtifactReviewError,
  ArtifactPublicationRollbackError,
} from './artifact-review.ts';
import { DataAccessError } from './data.ts';
import {
  legacyMcpScope,
  legacyMcpAccessError,
  type LegacyMcpExecution,
} from './mcp-legacy-execution.ts';

/** Host-generated bytes and quality/source receipts. These are not MCP args.
 * Reuses the existing publisher input verbatim; no guest filesystem paths. */
export type PreparedMcpDeliverable = Omit<
  Parameters<typeof publishWorkbenchArtifact>[0],
  'context' | 'sessionId' | 'callId'
>;

/** M1 prepared-publication subset of DeliverablesPort.create. Full Office,
 * review and management remain with their existing owners/M2 implementation. */
export function createLegacyDeliverablesMcpPort(storage: StoragePort) {
  return {
    async publishPrepared(
      authority: LegacyMcpExecution & { callId: string; requestId: string },
      prepared: PreparedMcpDeliverable,
      signal: AbortSignal,
    ) {
      signal.throwIfAborted();
      try {
        legacyMcpScope(authority);
        const artifact = await publishWorkbenchArtifact(
          {
            ...prepared,
            context: authority.context,
            sessionId: authority.sessionId,
            callId: authority.callId,
          },
          storage,
        );
        // A committed version remains committed after cancellation/ACK loss.
        // Native reconnect must reconcile this same call, never invent a new key.
        signal.throwIfAborted();
        return artifact;
      } catch (error) {
        signal.throwIfAborted();
        if (error instanceof DataAccessError)
          return legacyMcpAccessError(authority.requestId, error);
        if (
          error instanceof ArtifactReviewError ||
          error instanceof ArtifactPublicationRollbackError
        ) {
          const value = {
            code:
              error instanceof ArtifactPublicationRollbackError
                ? 'TOOL_PUBLICATION_ROLLED_BACK'
                : error.code,
            message: error.message,
            retryable: error instanceof ArtifactPublicationRollbackError,
          };
          return {
            isError: true as const,
            content: [{ type: 'text' as const, text: JSON.stringify(value) }],
          };
        }
        throw error;
      }
    },
  };
}
